using System;using System.IO;using System.Linq;using System.Windows.Forms;using System.Drawing;
namespace LoopPedal {static class RestartChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 public static void Run(){try{using(var e=new Engine())using(var peer=new Engine()){e.QuantizePeer=peer;float[] a=new float[96000];for(int i=0;i<48000;i++)a[i*2]=a[i*2+1]=(float)(.3*Math.Sin(i*.013));e.Layers.Add(new Layer{Original=a,Audio=a,Offset=700});e.LoopFrames=48000;e.LoopOrigin=700;e.Frame=8192;e.Playing=false;e.PlaybackPending=true;peer.Frame=5000;long clock=e.AudioFrame;e.LoopOrigin=-10000;e.Restart();Check(e.Frame==700&&!e.Playing&&!e.PlaybackPending,"stopped restart");Check(peer.Frame==5000&&e.AudioFrame==clock,"peer/global isolation");e.Playing=true;var output=new float[8192];e.Mix(output,4096);float last=output[output.Length-2];e.Restart();Check(e.Frame==700&&e.Playing,"playing restart");e.Mix(output,4096);Check(Math.Abs(last-output[0])<.02,"seek click");Check(object.ReferenceEquals(e.Layers[0].Original,a),"source changed");}using(var form=new Pedal(true)){form.Location=new Point(-20000,-20000);form.Show();form.VerifyRestartUi();form.VerifyTruncate();form.Close();}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"restart-tests.txt"),"PASS stopped/playing exact-origin restart; pending play cancelled; other bank and audio clock preserved; source unchanged; smooth playing transition; both UI buttons; no header overlap; truncate selected float samples/settings and Undo/Redo.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"restart-tests.txt"),"FAIL "+ex);Environment.ExitCode=1;}}
}
partial class Pedal {public void VerifyTruncate(){var bus=loopers[0];bus.Playing=false;float[] a=new float[96000];for(int i=0;i<a.Length;i++)a[i]=(float)Math.Sin(i*.03);var layer=new Layer{Name="Trim",Original=a,Audio=a,TrimStart=.2,TrimLength=.3,Reverse=true,Pitch=3,Stretch=1.25,Offset=23000};bus.Layers.Clear();bus.Layers.Add(layer);bus.LoopFrames=48000;TruncateLayer(bus,layer);if(layer.Original.Length!=28800||layer.TrimStart!=0||layer.TrimLength!=1||!layer.Reverse||layer.Pitch!=3||layer.Stretch!=1.25)throw new Exception("Truncate region/settings");for(int i=0;i<layer.Original.Length;i++)if(layer.Original[i]!=a[19200+i])throw new Exception("Truncate samples");bus.Undo();if(!object.ReferenceEquals(bus.Layers[0].Original,a)||bus.Layers[0].TrimStart!=.2)throw new Exception("Truncate Undo");bus.Redo();if(bus.Layers[0].Original.Length!=28800)throw new Exception("Truncate Redo");}
 public void VerifyRestartUi(){SetSingleMode(false);for(int i=0;i<2;i++){var bus=loopers[i];bus.Playing=false;bus.LoopOrigin=100+i;bus.Frame=9999;var button=bankPanels[i].Controls.Find("Restart"+i,true).Single() as RestartButton;if(button==null)throw new Exception("Restart button missing");button.PerformClick();if(bus.Frame!=bus.LoopOrigin||bus.Playing)throw new Exception("UI restart failed");if(button.Bounds.IntersectsWith(bankNames[i].Bounds)||button.Bounds.IntersectsWith(bankClocks[i].Bounds))throw new Exception("Header overlap");if(i==0&&button.Bounds.IntersectsWith(monitorPad.Bounds))throw new Exception("Headphone overlap");}using(var image=new Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(image,new Rectangle(Point.Empty,ClientSize));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"restart-ui.png"));}}}
}
